import { test, expect } from 'bun:test';
import { parseCsv } from '../src/csv.js';
test('parses header and rows', () => {
  expect(parseCsv('id,name\n1,Ann\n2,Bo\n')).toEqual([{ id: '1', name: 'Ann' }, { id: '2', name: 'Bo' }]);
});
test('no trailing newline, empty values', () => {
  expect(parseCsv('a,b\n1,')).toEqual([{ a: '1', b: '' }]);
});
test('header only', () => expect(parseCsv('a,b\n')).toEqual([]));

