import { test, expect } from 'bun:test';
import { parseCsv } from '../src/csv.js';
test('quoted commas and doubled quotes stay in the value', () => {
  expect(parseCsv('name,note\n"Smith, Ann","said ""hi"""\n')).toEqual([{ name: 'Smith, Ann', note: 'said "hi"' }]);
});
test('a line break inside quotes stays in the value', () => {
  expect(parseCsv('id,note\n1,"line one\nline two"\n2,plain\n')).toEqual([{ id: '1', note: 'line one\nline two' }, { id: '2', note: 'plain' }]);
});
test('CRLF line endings, no phantom last row', () => {
  expect(parseCsv('a,b\r\n1,2\r\n3,4\r\n')).toEqual([{ a: '1', b: '2' }, { a: '3', b: '4' }]);
});
